// Configure WordPress.org plugin directory search (zero API keys required)
const search = 'woocommerce';
const perPage = 5;
const requestUrl = `https://api.wordpress.org/plugins/info/1.2/?action=query_plugins&request%5Bsearch%5D=${encodeURIComponent(search)}&request%5Bper_page%5D=${perPage}`;

return [{ json: { search, perPage, requestUrl } }];

// Rank plugins by 1-2 star churn density and prepare 1-star RSS review URLs
const payload = $input.first().json || {};
const plugins = Array.isArray(payload.plugins) ? payload.plugins : [];

const scored = plugins.map((p) => {
  const ratings = p.ratings || {};
  const oneStar = Number(ratings['1'] || 0);
  const twoStar = Number(ratings['2'] || 0);
  const totalReviews = Object.values(ratings).reduce((acc, n) => acc + Number(n || 0), 0);
  const lowStarCount = oneStar + twoStar;
  const lowStarRatioPct = totalReviews > 0 ? Number(((lowStarCount / totalReviews) * 100).toFixed(1)) : 0;
  const threads = Number(p.support_threads || 0);
  const resolved = Number(p.support_threads_resolved || 0);
  const unresolvedThreads = Math.max(0, threads - resolved);
  const cleanName = String(p.name || p.slug || '').replace(/<[^>]+>/g, '').replace(/&#8211;|&amp;/g, '-').trim();

  return {
    slug: p.slug,
    name: cleanName,
    version: p.version || null,
    activeInstalls: Number(p.active_installs || 0),
    ratingOutOf100: Number(p.rating || 0),
    oneStarCount: oneStar,
    twoStarCount: twoStar,
    lowStarRatioPct,
    supportThreads: threads,
    unresolvedThreads,
    homepage: p.homepage || null,
    reviewsRssUrl: `https://wordpress.org/support/plugin/${encodeURIComponent(p.slug)}/reviews/feed/?filter=1`,
  };
});

// Pick top 3 plugins sorted by 1-star volume for live RSS complaint extraction
scored.sort((a, b) => b.oneStarCount - a.oneStarCount);
return scored.slice(0, 3).map((item) => ({ json: item }));

// Parse 1-star WordPress.org RSS review feeds and categorize churn pain points
const items = $input.all();
const stats = $('Score Plugin Churn & Build RSS URLs').all();
const painRules = {
  billing_pricing: /\b(price|pricing|expensive|fee|billing|subscription|refund|charge|cost|greedy|paid)\b/i,
  bugs_breakage: /\b(broken|bug|crash|error|fail|conflict|update|slow|fatal|timeout|doesn.?t work)\b/i,
  support_churn: /\b(support|no reply|ignored|useless|worst|waste|uninstall|switch|alternative)\b/i,
};

const out = [];
for (let i = 0; i < items.length; i++) {
  const xml = String(items[i].json.data ?? items[i].json.body ?? '');
  const meta = (stats[i] && stats[i].json) ? stats[i].json : {};
  const matches = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].slice(0, 5);

  for (const m of matches) {
    const block = m[1];
    const getTag = (tag) => {
      const hit = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
      return hit ? hit[1].replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
    };
    const title = getTag('title');
    const link = getTag('link');
    const pubDate = getTag('pubDate');
    const desc = getTag('description');
    const combined = `${title} ${desc}`;
    const painCategories = Object.entries(painRules)
      .filter(([, rx]) => rx.test(combined))
      .map(([k]) => k);

    out.push({
      json: {
        pluginSlug: meta.slug || null,
        pluginName: meta.name || null,
        activeInstalls: meta.activeInstalls ?? null,
        oneStarCount: meta.oneStarCount ?? null,
        unresolvedThreads: meta.unresolvedThreads ?? null,
        reviewTitle: title,
        pubDate,
        painCategories,
        excerpt: desc.slice(0, 260),
        reviewUrl: link,
        agentSummary: `[${meta.slug}] 1-star (${painCategories.join(',') || 'general'}): ${title}`,
      },
    });
  }
}

return out.length ? out : [{ json: { status: 'no_1star_rss_items_parsed' } }];
